keyConcepts.codeExample:
type Result<T, E> =
  | { ok: true; value: T }
  | { ok: false; error: E };

interface Transfer { id: string; amountCents: number; }
type TransferError = 'INSUFFICIENT_FUNDS' | 'ACCOUNT_NOT_FOUND';

function transferFunds(balanceCents: number, amountCents: number): Result<Transfer, TransferError> {
  if (amountCents > balanceCents) {
    return { ok: false, error: 'INSUFFICIENT_FUNDS' };
  }
  return { ok: true, value: { id: 'TRF-1', amountCents } };
}

const result = transferFunds(1000, 5000);
if (!result.ok) {
  console.error(`Virement refusé : ${result.error}`);
} else {
  console.log(`Virement ${result.value.id} effectué`);
}

